"""Cryptographic helpers: Ed25519 verification, SHA-256 ids and Merkle roots."""
from __future__ import annotations

import hashlib
import hmac
import json
import re

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)


def canonical_message(sender: str, recipient: str, amount: int) -> bytes:
    """Deterministic byte representation of a transaction payload.

    The payload is serialized as compact JSON with sorted keys so the same
    (from, to, amount) triple always yields identical bytes on every client.
    """
    payload = {"amount": amount, "from": sender, "to": recipient}
    return json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def compute_tx_id(message: bytes) -> str:
    """SHA-256 hex digest of the canonical transaction message."""
    return sha256_hex(message)


def generate_private_key() -> str:
    """Generate a fresh Ed25519 private seed as 64 lowercase hex chars."""
    return Ed25519PrivateKey.generate().private_bytes(
        serialization.Encoding.Raw,
        serialization.PrivateFormat.Raw,
        serialization.NoEncryption(),
    ).hex()


def derive_public_key(private_key_hex: str) -> str | None:
    """Derive the 64-hex Ed25519 public key from a 64-hex private seed.

    Returns None for malformed hex or a wrong-length seed rather than raising,
    so callers can treat every malformed key uniformly as a 400.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return _public_hex(private_key)


def _public_hex(private_key: Ed25519PrivateKey) -> str:
    return private_key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


def sign_message(private_key_hex: str, message: bytes) -> str | None:
    """Sign ``message`` with an Ed25519 seed (64 hex chars); hex signature.

    Returns None for a malformed private key rather than raising.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return private_key.sign(message).hex()


def verify_signature(public_key_hex: str, message: bytes, signature_hex: str) -> bool:
    """Verify an Ed25519 signature (public key and signature are hex strings).

    Returns False for malformed hex or wrong key/signature lengths rather than
    raising, so callers can treat every verification failure uniformly.
    """
    try:
        public_bytes = bytes.fromhex(public_key_hex)
        signature_bytes = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    if len(public_bytes) != 32 or len(signature_bytes) != 64:
        return False
    try:
        public_key = Ed25519PublicKey.from_public_bytes(public_bytes)
        public_key.verify(signature_bytes, message)
    except (InvalidSignature, ValueError):
        return False
    return True


# Merkle root of an empty transaction list; fixed so genesis blocks are identical.
EMPTY_MERKLE_ROOT = sha256_hex(b"")


def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]


# A SHA-256 digest rendered as 64 lowercase hexadecimal characters.
_HEX64_RE = re.compile(r"[0-9a-f]{64}")

# A 64-byte Ed25519 signature rendered as 128 lowercase hex characters.
_HEX128_RE = re.compile(r"[0-9a-f]{128}")

# Maximum Merkle depth we accept: 64 sibling levels already cover trees with up
# to 2**64 leaves, so a longer sibling path is necessarily malformed.
MAX_MERKLE_DEPTH = 64


def _is_hex64(value: object) -> bool:
    return isinstance(value, str) and _HEX64_RE.fullmatch(value) is not None


def is_hex64(value: object) -> bool:
    """True iff ``value`` is a 64-char lowercase SHA-256 hex string."""
    return _is_hex64(value)


def is_hex128(value: object) -> bool:
    """True iff ``value`` is a 128-char lowercase Ed25519 signature hex string."""
    return isinstance(value, str) and _HEX128_RE.fullmatch(value) is not None


def merkle_proof(tx_ids: list[str], index: int) -> list[dict]:
    """Sibling path from the leaf at ``index`` up to the Merkle root.

    Mirrors :func:`merkle_root`: levels hash ``sha256(left + right)`` hex pairs
    and a lone odd node is paired with itself. Each returned item has a
    ``direction`` ("left" or "right") recording which side the *sibling* sits
    on relative to the path node, and the sibling's ``hash``. Items are ordered
    from the leaf level toward the root. Raises ValueError for an empty list or
    an out-of-range index.
    """
    if not tx_ids:
        raise ValueError("cannot build a Merkle proof for an empty tree")
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 0 or index >= len(tx_ids):
        raise ValueError("transaction index out of range")

    level = list(tx_ids)
    position = index
    siblings: list[dict] = []
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        if position % 2 == 0:
            # Path node is the left child; sibling sits on its right.
            siblings.append({"direction": "right", "hash": level[position + 1]})
        else:
            # Path node is the right child; sibling sits on its left.
            siblings.append({"direction": "left", "hash": level[position - 1]})
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
        position //= 2
    return siblings


def verify_merkle_proof(
    tx_id: str,
    siblings: list[dict],
    merkle_root: str,
    block_hash: str,
    expected_block_hash: str,
) -> bool:
    """Verify a Merkle proof and bind it to a specific block hash.

    Re-hashes the leaf (``tx_id``) with the sibling path from leaf to root and
    compares the result with ``merkle_root``; ``block_hash`` must additionally
    equal ``expected_block_hash``. Every malformed input (non-64-char lowercase
    hex hash, illegal direction, non-list path, excessive depth) and every
    mismatch returns False rather than raising.
    """
    try:
        if not _is_hex64(tx_id):
            return False
        if not _is_hex64(merkle_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_block_hash):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        current = tx_id
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            if direction == "left":
                pair = sibling_hash + current
            elif direction == "right":
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))

        if not hmac.compare_digest(current, merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# Exact, ordered key sets of a batch Merkle-proof response document. They let
# verify_merkle_proof_bundle reject missing/extra keys *and* a wrong key order.
_BUNDLE_TOP_KEYS = ("height", "block_hash", "merkle_root", "transaction_ids", "proofs")
_BUNDLE_PROOF_KEYS = ("tx_id", "index", "siblings")
_BUNDLE_SIBLING_KEYS = ("direction", "hash")


def _exact_keys(value: object, keys: tuple[str, ...]) -> bool:
    """True iff ``value`` is a dict with exactly ``keys``, in that insertion order."""
    return isinstance(value, dict) and tuple(value.keys()) == keys


def verify_merkle_proof_bundle(
    bundle: object,
    expected_block_hash: object,
    expected_merkle_root: object,
) -> bool:
    """Strictly verify a batch Merkle-proof bundle offline.

    The bundle mirrors POST /v1/blocks/{height}/proofs::

        {"height": H, "block_hash": B, "merkle_root": R,
         "transaction_ids": [id, ...],     # ALL block leaves, ascending
         "proofs": [{"tx_id", "index", "siblings"}, ...]}  # requested subset

    ``transaction_ids`` is the block's complete, ascending leaf list; ``proofs``
    covers the requested tx_ids (a subset of it), itself sorted by tx_id. Every
    proof's leaf-to-root sibling path is re-hashed with the same pairing rules
    as :func:`merkle_root` (``sha256(left + right)`` hex pairs, a lone odd node
    paired with itself); the root is additionally recomputed directly from
    ``transaction_ids`` and must equal both the bundle's ``merkle_root`` and
    ``expected_merkle_root``, while ``block_hash`` must equal
    ``expected_block_hash``. Each proof ``index`` must be the tx_id's exact
    position in ``transaction_ids`` and its path must agree with that index at
    every level.

    Every defect — a missing/extra key, a wrong key order, a wrong type, a
    non-boolean/negative height, a duplicate/non-hex/non-string/unsorted tx_id,
    an unknown or duplicated proof tx_id, an out-of-range index, a path
    inconsistent with the index (including the phantom self-pair slot), an
    illegal direction or hash, excessive depth, an empty proof list, a tampered
    leaf list/root or block hash — returns False rather than raising.
    """
    try:
        if not _exact_keys(bundle, _BUNDLE_TOP_KEYS):
            return False
        if not _is_hex64(expected_block_hash) or not _is_hex64(expected_merkle_root):
            return False
        height = bundle["height"]
        block_hash = bundle["block_hash"]
        bundle_root = bundle["merkle_root"]
        transaction_ids = bundle["transaction_ids"]
        proofs = bundle["proofs"]

        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            return False
        if not _is_hex64(block_hash):
            return False
        if not _is_hex64(bundle_root):
            return False
        if not isinstance(transaction_ids, list) or not transaction_ids:
            return False
        if not isinstance(proofs, list) or not proofs:
            return False
        if any(not _is_hex64(tx_id) for tx_id in transaction_ids):
            return False
        # Unique leaves ...
        if len(set(transaction_ids)) != len(transaction_ids):
            return False
        # ... in ascending tx_id order, matching the block's leaf ordering.
        if transaction_ids != sorted(transaction_ids):
            return False
        # The root is recomputed straight from the claimed leaf list, so the
        # list can never be tampered with independently of the paths.
        if not hmac.compare_digest(merkle_root(transaction_ids), bundle_root):
            return False

        positions = {tx_id: i for i, tx_id in enumerate(transaction_ids)}
        proof_ids: list[str] = []
        leaf_count = len(transaction_ids)
        for proof in proofs:
            if not _exact_keys(proof, _BUNDLE_PROOF_KEYS):
                return False
            tx_id = proof["tx_id"]
            index = proof["index"]
            siblings = proof["siblings"]
            if not _is_hex64(tx_id) or tx_id not in positions:
                return False
            if tx_id in proof_ids:
                return False
            if isinstance(index, bool) or not isinstance(index, int):
                return False
            # The index must be exactly the tx_id's leaf position; anything
            # else is a mismatch or out of range regardless of supplied hashes.
            if index != positions[tx_id] or not 0 <= index < leaf_count:
                return False
            if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
                return False

            # A depth-D path addresses one of 2**D leaf slots.
            depth = len(siblings)
            if index >= (1 << depth):
                return False
            current = tx_id
            position = index
            for item in siblings:
                if not _exact_keys(item, _BUNDLE_SIBLING_KEYS):
                    return False
                direction = item["direction"]
                sibling_hash = item["hash"]
                if not _is_hex64(sibling_hash):
                    return False
                # The odd-node promotion pairs the last (even-positioned) node
                # with a copy of itself, so a genuine self-pair always points
                # at a right sibling. A left sibling equal to the current node
                # addresses the phantom duplicate slot, which is never a real
                # leaf. The path must also agree with the index at every
                # level: an even position is the left child (sibling on its
                # right), an odd position the right child.
                if direction == "left":
                    if position % 2 == 0 or sibling_hash == current:
                        return False
                    pair = sibling_hash + current
                elif direction == "right":
                    if position % 2 == 1:
                        return False
                    pair = current + sibling_hash
                else:
                    return False
                current = sha256_hex(pair.encode("ascii"))
                position //= 2

            if not hmac.compare_digest(current, bundle_root):
                return False
            proof_ids.append(tx_id)

        # Proofs must be unique and ordered by tx_id ascending.
        if proof_ids != sorted(proof_ids):
            return False

        if not hmac.compare_digest(bundle_root, expected_merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# -- account state Merkle tree ----------------------------------------------


def account_state_leaf(
    account: str, balance: int, confirmed_transactions: list[str]
) -> str:
    """SHA-256 leaf of one account's confirmed state.

    The leaf is ``sha256(utf8(JSON))`` of the canonical compact JSON document
    ``{"account":a,"balance":b,"confirmed_transactions":T}`` serialized with
    ``sort_keys=True``, ``ensure_ascii=False`` and ``separators=(",",":")``.
    ``T`` keeps its original (on-chain) order; ``sort_keys`` only orders the
    three top-level keys.
    """
    document = {
        "account": account,
        "balance": balance,
        "confirmed_transactions": confirmed_transactions,
    }
    raw = json.dumps(
        document, sort_keys=True, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    return sha256_hex(raw)


def account_state_root(leaves: list[str]) -> str:
    """Merkle root of account-state leaves ordered by ascending account.

    Uses the same pairing rules as :func:`merkle_root` (hex-string pairs
    hashed ``sha256(left + right)``, a lone odd node paired with itself); an
    empty account set has the same root as an empty tx list.
    """
    return merkle_root(leaves)


def verify_account_proof(
    proof: object,
    expected_root: object,
    expected_height: object,
    expected_hash: object,
) -> bool:
    """Verify an account-state Merkle proof offline.

    Recomputes the account leaf from
    ``{account, balance, confirmed_transactions}``, walks the leaf-to-root
    ``siblings`` path, and requires the recomputed root to equal both the
    proof's ``state_root`` and ``expected_root``, while ``height`` /
    ``block_hash`` anchor the tree to the expected confirmed tip. Every
    malformed input — a non-64-char lowercase hex hash or anchor, an illegal
    direction, an illegal index, a malformed leaf/balance/transaction list, a
    path inconsistent with the index, excessive depth — returns False rather
    than raising.
    """
    try:
        if not isinstance(proof, dict):
            return False
        account = proof.get("account")
        balance = proof.get("balance")
        transactions = proof.get("confirmed_transactions")
        index = proof.get("index")
        state_root = proof.get("state_root")
        height = proof.get("height")
        block_hash = proof.get("block_hash")
        siblings = proof.get("siblings")

        if not isinstance(account, str) or not account:
            return False
        if isinstance(balance, bool) or not isinstance(balance, int) or balance < 0:
            return False
        if not isinstance(transactions, list):
            return False
        if any(not _is_hex64(tx_id) for tx_id in transactions):
            return False
        if isinstance(index, bool) or not isinstance(index, int) or index < 0:
            return False
        if not isinstance(height, bool) and isinstance(height, int):
            if height < 0:
                return False
        else:
            return False
        if not _is_hex64(state_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_hash):
            return False
        if not _is_hex64(expected_root):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        # The leaf is always recomputed from the proof's own triple; a
        # client-supplied leaf value is never trusted.
        depth = len(siblings)
        # A depth-D path addresses one of 2**D leaf slots; a single-leaf tree
        # (D == 0) can only ever be index 0. An index outside that range is
        # illegal regardless of any hashes the caller supplies.
        if index >= (1 << depth):
            return False
        current = account_state_leaf(account, balance, transactions)
        position = index
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            # The odd-node promotion pairs the last (even-positioned) node
            # with a copy of itself, so a genuine self-pair always points at a
            # right sibling. A left sibling equal to the current node addresses
            # the phantom duplicate slot, which is never a real account.
            if direction == "left" and sibling_hash == current:
                return False
            # The path must agree with the index: at every level an even
            # position is the left child (sibling on its right) and an odd
            # position the right child.
            if direction == "left":
                if position % 2 == 0:
                    return False
                pair = sibling_hash + current
            elif direction == "right":
                if position % 2 == 1:
                    return False
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))
            position //= 2

        if not hmac.compare_digest(current, state_root):
            return False
        if not hmac.compare_digest(current, expected_root):
            return False
        if height != expected_height:
            return False
        if not hmac.compare_digest(block_hash, expected_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False

"""Append-only audit log hash chaining, checkpoints and offline verification.

Every audit event carries two SHA-256 links:

* ``prev_hash``  — the previous event's ``event_hash``; 64 ASCII zeroes for
  the first event;
* ``event_hash`` — ``sha256(prev_hash ASCII || canonical-event UTF-8)`` where
  the canonical event is the event with both hash fields removed, serialized
  as sorted-key compact JSON (``sort_keys=True, separators=(",", ":")``,
  non-ASCII characters emitted as raw UTF-8).

``audit_checkpoint`` is ``{"event_id", "event_hash"}`` pinning the latest
event: a fresh/empty log checks at ``{0, "0"*64}``. Offline verification walks
one or more exported pages, checking each page anchor, the dense event ids and
every link, and requires every page to pin the identical checkpoint with the
final page's last event (or the empty log) matching it.

A page may additionally carry ``checkpoint_auth`` — an Ed25519 signature over
``SHA256(sorted-compact UTF-8 JSON of {genesis_hash, checkpoint,
key_version})``. ``verify_export(document, trust)`` only checks that envelope
when a trust document (``genesis_hash`` plus a version-ascending
``audit_signers`` list) is supplied; authentication failures then use the
``auth`` error category.
"""
from __future__ import annotations

import hashlib
import json

from . import crypto

# Sentinel previous hash of the first audit event (and checkpoint of an empty
# log): 64 ASCII zeroes.
ZERO_HASH = "0" * 64

# Names of the two link fields excluded from the hashed canonical event.
HASH_FIELDS = ("prev_hash", "event_hash")

# Public offline-verification error categories.
ERR_INPUT = "input"
ERR_INTEGRITY = "integrity"
ERR_AUTH = "auth"


class AuditChainError(ValueError):
    """A persisted audit hash chain or checkpoint failed strict validation.

    Carries a human-readable ``reason``; the persistence layer maps it onto a
    ``StateRecoveryError`` tagged with the offending snapshot path.
    """

    def __init__(self, reason: str) -> None:
        self.reason = reason
        super().__init__(reason)


class _VerifyError(Exception):
    """Internal control-flow exception carrying the public error category."""

    def __init__(self, category: str) -> None:
        self.category = category
        super().__init__(category)


def _is_plain_int(value: object) -> bool:
    """Plain integer test; booleans are rejected (bool subclasses int)."""
    return isinstance(value, int) and not isinstance(value, bool)


def canonical_event(event: dict) -> bytes:
    """Sorted-key compact UTF-8 JSON of the event with both hash fields removed.

    This is the exact byte document chained into ``event_hash``; stripping the
    links makes the hash independent of any re-serialization of the stored
    event object.
    """
    stripped = {key: value for key, value in event.items() if key not in HASH_FIELDS}
    return json.dumps(
        stripped, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def event_hash(prev_hash: str, event: dict) -> str:
    """SHA-256 hex of ``prev_hash`` ASCII bytes followed by the canonical event."""
    return hashlib.sha256(prev_hash.encode("ascii") + canonical_event(event)).hexdigest()


def link_events(events: list[dict]) -> list[dict]:
    """Return copies of ``events`` with dense ids and fresh hash links.

    Event ids are renumbered 1..N; the first event gets the all-zero
    ``prev_hash`` and every later event links to its predecessor. Does not
    mutate the input.
    """
    linked: list[dict] = []
    prev_hash = ZERO_HASH
    for index, event in enumerate(events):
        linked_event = dict(event)
        linked_event["event_id"] = index + 1
        linked_event["prev_hash"] = prev_hash
        linked_event["event_hash"] = event_hash(prev_hash, linked_event)
        linked.append(linked_event)
        prev_hash = linked_event["event_hash"]
    return linked


def make_checkpoint(events: list[dict]) -> dict:
    """``{"event_id", "event_hash"}`` pinning the last event (or the zero root)."""
    if events:
        return {
            "event_id": len(events),
            "event_hash": events[-1]["event_hash"],
        }
    return {"event_id": 0, "event_hash": ZERO_HASH}


# Fields of a page's checkpoint authentication envelope.
AUTH_FIELDS = ("key_version", "signature")


def checkpoint_auth_object(
    genesis_hash: str, checkpoint: dict, key_version: int
) -> dict:
    """The exact JSON object covered by a checkpoint authentication signature.

    ``{"genesis_hash", "checkpoint": {"event_id", "event_hash"},
    "key_version"}`` — the genesis anchor pins the deployment, the checkpoint
    pins the audit log head and the key version selects the verifying public
    key.
    """
    return {
        "genesis_hash": genesis_hash,
        "checkpoint": {
            "event_id": checkpoint["event_id"],
            "event_hash": checkpoint["event_hash"],
        },
        "key_version": key_version,
    }


def checkpoint_auth_bytes(auth_object: dict) -> bytes:
    """Sorted-key compact UTF-8 JSON of a checkpoint authentication object."""
    return json.dumps(
        auth_object, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def sign_checkpoint_auth(
    private_key_hex: str, genesis_hash: str, checkpoint: dict, key_version: int
) -> str:
    """Ed25519-sign SHA-256 of the canonical checkpoint authentication object.

    Returns the 128-hex signature, or None when the private key is malformed.
    """
    auth_object = checkpoint_auth_object(genesis_hash, checkpoint, key_version)
    digest = hashlib.sha256(checkpoint_auth_bytes(auth_object)).digest()
    return crypto.sign_message(private_key_hex, digest)


def verify_checkpoint_auth(
    public_key_hex: str,
    genesis_hash: str,
    checkpoint: dict,
    key_version: int,
    signature_hex: str,
) -> bool:
    """Verify one checkpoint authentication signature. Never raises."""
    auth_object = checkpoint_auth_object(genesis_hash, checkpoint, key_version)
    digest = hashlib.sha256(checkpoint_auth_bytes(auth_object)).digest()
    return crypto.verify_signature(public_key_hex, digest, signature_hex)


def validate_event_chain(events: object) -> None:
    """Strictly validate a persisted event list's dense ids and hash links.

    ``event_id`` values must be exactly 1..N; each ``prev_hash`` must equal the
    previous event's ``event_hash`` (all zeroes for the first event) and every
    ``event_hash`` must recompute from the event with both hash fields removed.
    Raises AuditChainError on the first defect.
    """
    if not isinstance(events, list):
        raise AuditChainError("'audit_events' must be a list")
    prev_hash = ZERO_HASH
    for index, event in enumerate(events):
        event_id = index + 1
        if not isinstance(event, dict):
            raise AuditChainError(f"audit event {event_id} must be an object")
        if not _is_plain_int(event.get("event_id")) or event["event_id"] != event_id:
            raise AuditChainError(
                f"audit event at position {index} has event_id "
                f"{event.get('event_id')!r}, expected {event_id}"
            )
        stored_prev = event.get("prev_hash")
        if not crypto.is_hex64(stored_prev) or stored_prev != prev_hash:
            raise AuditChainError(
                f"audit event {event_id} has a mismatched prev_hash"
            )
        stored_hash = event.get("event_hash")
        if not crypto.is_hex64(stored_hash):
            raise AuditChainError(
                f"audit event {event_id} has an invalid event_hash"
            )
        if event_hash(prev_hash, event) != stored_hash:
            raise AuditChainError(
                f"audit event {event_id} has a mismatched event_hash"
            )
        prev_hash = stored_hash


def validate_checkpoint(checkpoint: object, events: list[dict]) -> None:
    """Validate an ``audit_checkpoint`` against the recovered event list.

    It must be ``{"event_id": N, "event_hash": H}`` with N the (non-negative)
    number of events and H the last event's hash, or the all-zero root when the
    log is empty. Raises AuditChainError on any defect.
    """
    if not isinstance(checkpoint, dict):
        raise AuditChainError("'audit_checkpoint' must be an object")
    event_id = checkpoint.get("event_id")
    event_hash_value = checkpoint.get("event_hash")
    if not _is_plain_int(event_id) or event_id < 0:
        raise AuditChainError("audit_checkpoint.event_id must be a non-negative integer")
    if not crypto.is_hex64(event_hash_value):
        raise AuditChainError("audit_checkpoint.event_hash must be 64 lowercase hex chars")
    expected = make_checkpoint(events)
    if event_id != expected["event_id"]:
        raise AuditChainError(
            f"audit_checkpoint.event_id is {event_id}, log ends at "
            f"{expected['event_id']}"
        )
    if event_hash_value != expected["event_hash"]:
        raise AuditChainError("audit_checkpoint.event_hash does not match the log head")


def verify_export(document: object, trust: object = None) -> dict:
    """Offline-verify one audit export page or an ordered list of pages.

    A page has the server shape
    ``{items, total, next_cursor, anchor_hash, checkpoint}``. Every page
    must pin the identical checkpoint, each page anchor must equal the
    running predecessor hash, item event ids must be dense and consecutive
    across pages, every ``prev_hash``/``event_hash`` pair must recompute,
    pagination counters must be self-consistent and the last page's tail
    must equal that shared checkpoint.

    When ``trust`` is None (the default) no authentication is attempted and
    the behaviour is unchanged. When a trust document is supplied it must
    carry ``genesis_hash`` and a version-ascending ``audit_signers`` list
    (``{version, public_key, activated_event_id}``); every page must then
    carry the same ``checkpoint_auth`` envelope
    (``{key_version, signature}``) binding the same checkpoint, the key
    version must be known and activated at or before the checkpoint, and the
    Ed25519 signature over
    ``SHA256(sorted-compact UTF-8 JSON of {genesis_hash, checkpoint,
    key_version})`` must verify against that version's public key.

    Returns ``{"ok": True, "checkpoint": {...}}`` or
    ``{"ok": False, "error": "input" | "integrity" | "auth"}``. Never raises
    for malformed input.
    """
    try:
        pages = _coerce_pages(document)
        checkpoint = _verify_pages(pages)
        if trust is not None:
            _verify_checkpoint_auth(pages, checkpoint, trust)
    except _VerifyError as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        # Defensive: structurally unforeseeable inputs report rather than crash.
        return {"ok": False, "error": ERR_INPUT}
    return {"ok": True, "checkpoint": checkpoint}


def _coerce_pages(document: object) -> list[dict]:
    """Normalize a single page object / list of pages, validating basic shape."""
    if isinstance(document, dict):
        pages = [document]
    elif isinstance(document, list) and (
        not document or all(isinstance(page, dict) for page in document)
    ):
        pages = document
    else:
        raise _VerifyError(ERR_INPUT)
    if not pages:
        raise _VerifyError(ERR_INPUT)
    return pages


def _parse_page_shape(page: object) -> dict:
    """Validate a page's structural fields; returns the dict on success."""
    if not isinstance(page, dict):
        raise _VerifyError(ERR_INPUT)
    for field in ("items", "total", "next_cursor", "anchor_hash", "checkpoint"):
        if field not in page:
            raise _VerifyError(ERR_INPUT)
    items = page["items"]
    total = page["total"]
    next_cursor = page["next_cursor"]
    anchor_hash = page["anchor_hash"]
    checkpoint = page["checkpoint"]
    if not isinstance(items, list):
        raise _VerifyError(ERR_INPUT)
    if not _is_plain_int(total) or total < 0:
        raise _VerifyError(ERR_INPUT)
    if next_cursor is not None and (not _is_plain_int(next_cursor) or next_cursor < 0):
        raise _VerifyError(ERR_INPUT)
    if not crypto.is_hex64(anchor_hash):
        raise _VerifyError(ERR_INPUT)
    if not isinstance(checkpoint, dict):
        raise _VerifyError(ERR_INPUT)
    checkpoint_id = checkpoint.get("event_id")
    checkpoint_hash = checkpoint.get("event_hash")
    if not _is_plain_int(checkpoint_id) or checkpoint_id < 0:
        raise _VerifyError(ERR_INPUT)
    if not crypto.is_hex64(checkpoint_hash):
        raise _VerifyError(ERR_INPUT)
    return page


def _verify_pages(pages: list[dict]) -> dict:
    """Walk every page in order; return the shared checkpoint on success."""
    running_id = 0
    running_hash = ZERO_HASH
    first_checkpoint: dict | None = None
    for page in pages:
        page = _parse_page_shape(page)
        items = page["items"]
        total = page["total"]
        next_cursor = page["next_cursor"]
        checkpoint = page["checkpoint"]

        # Every page of one export pins the identical checkpoint; a replaced
        # or regressed checkpoint on any page breaks the export as a whole.
        if first_checkpoint is None:
            first_checkpoint = checkpoint
        elif checkpoint != first_checkpoint:
            raise _VerifyError(ERR_INTEGRITY)
        # The export is unfiltered, so a page's total is the log length its
        # checkpoint was taken over.
        if checkpoint["event_id"] != total:
            raise _VerifyError(ERR_INTEGRITY)
        # This page begins exactly where verification currently stands: the
        # declared anchor is the predecessor hash of its first item (or of the
        # cursor position for an empty page).
        if page["anchor_hash"] != running_hash:
            raise _VerifyError(ERR_INTEGRITY)

        for item in items:
            if not isinstance(item, dict):
                raise _VerifyError(ERR_INPUT)
            event_id = item.get("event_id")
            prev_hash = item.get("prev_hash")
            stored_hash = item.get("event_hash")
            if not _is_plain_int(event_id):
                raise _VerifyError(ERR_INPUT)
            if not crypto.is_hex64(prev_hash) or not crypto.is_hex64(stored_hash):
                raise _VerifyError(ERR_INPUT)
            if event_id != running_id + 1:
                raise _VerifyError(ERR_INTEGRITY)
            if prev_hash != running_hash:
                raise _VerifyError(ERR_INTEGRITY)
            if event_hash(running_hash, item) != stored_hash:
                raise _VerifyError(ERR_INTEGRITY)
            running_id = event_id
            running_hash = stored_hash

        # Pagination self-consistency: a non-null next_cursor continues exactly
        # after this page and stays below total; a server page with limit >= 1
        # is therefore non-empty whenever it is not the last page. A null
        # next_cursor ends exactly at the total.
        if next_cursor is None:
            if running_id != total:
                raise _VerifyError(ERR_INTEGRITY)
        else:
            if not items or next_cursor != running_id or next_cursor >= total:
                raise _VerifyError(ERR_INTEGRITY)

    # The final page must end exactly on the checkpoint every page pinned.
    assert first_checkpoint is not None
    if (
        running_id != first_checkpoint["event_id"]
        or running_hash != first_checkpoint["event_hash"]
    ):
        raise _VerifyError(ERR_INTEGRITY)
    return dict(first_checkpoint)


def _parse_trust_signers(trust: object) -> tuple[str, dict[int, dict]]:
    """Strictly parse a trust document's genesis anchor and audit signers.

    Returns ``(genesis_hash, {version: {public_key, activated_event_id}})``.
    Versions must be dense and ascending starting at 1, the first
    ``activated_event_id`` must be 0 and later activation ids must be strictly
    ascending. Any defect is an input error.
    """
    if not isinstance(trust, dict):
        raise _VerifyError(ERR_INPUT)
    genesis_hash = trust.get("genesis_hash")
    if not crypto.is_hex64(genesis_hash):
        raise _VerifyError(ERR_INPUT)
    raw_signers = trust.get("audit_signers")
    if not isinstance(raw_signers, list) or not raw_signers:
        raise _VerifyError(ERR_INPUT)
    signers: dict[int, dict] = {}
    previous_activated: int | None = None
    for position, entry in enumerate(raw_signers):
        if not isinstance(entry, dict):
            raise _VerifyError(ERR_INPUT)
        version = entry.get("version")
        public_key = entry.get("public_key")
        activated = entry.get("activated_event_id")
        if not _is_plain_int(version) or version != position + 1:
            raise _VerifyError(ERR_INPUT)
        if not crypto.is_hex64(public_key):
            raise _VerifyError(ERR_INPUT)
        if not _is_plain_int(activated) or activated < 0:
            raise _VerifyError(ERR_INPUT)
        if position == 0:
            if activated != 0:
                raise _VerifyError(ERR_INPUT)
        elif activated <= previous_activated:
            # A gap in versions is already rejected above; an activation id
            # that retreats (or stands still) is likewise a malformed list.
            raise _VerifyError(ERR_INPUT)
        previous_activated = activated
        signers[version] = {
            "public_key": public_key,
            "activated_event_id": activated,
        }
    return genesis_hash, signers


def _verify_checkpoint_auth(
    pages: list[dict], checkpoint: dict, trust: object
) -> None:
    """Verify the Ed25519 checkpoint authentication carried by every page.

    Every page must carry the same ``checkpoint_auth`` envelope
    (``{key_version, signature}``) and pin the same checkpoint; the key
    version must identify a signer already activated at or before the
    checkpoint and the signature must verify over
    ``SHA256(sorted-compact UTF-8 JSON of {genesis_hash, checkpoint,
    key_version})`` under the trust document's anchor. Structural defects are
    input errors; missing, unknown-version, cross-page-inconsistent or
    cryptographically invalid authentication is an auth error; a page whose
    checkpoint differs from the verified head is an integrity error.
    """
    genesis_hash, signers = _parse_trust_signers(trust)
    envelopes: list[object] = []
    for page in pages:
        if page.get("checkpoint") != checkpoint:
            # Two pages of one export must pin the same log head.
            raise _VerifyError(ERR_INTEGRITY)
        envelope = page.get("checkpoint_auth")
        if envelope is None:
            raise _VerifyError(ERR_AUTH)
        if not isinstance(envelope, dict):
            raise _VerifyError(ERR_INPUT)
        key_version = envelope.get("key_version")
        signature = envelope.get("signature")
        if not _is_plain_int(key_version) or key_version < 1:
            raise _VerifyError(ERR_INPUT)
        if not isinstance(signature, str) or not crypto.is_hex128(signature):
            raise _VerifyError(ERR_INPUT)
        envelopes.append({"key_version": key_version, "signature": signature})

    first = envelopes[0]
    for envelope in envelopes[1:]:
        if envelope != first:
            raise _VerifyError(ERR_AUTH)

    signer = signers.get(first["key_version"])
    if signer is None:
        raise _VerifyError(ERR_AUTH)
    # A trust document may not describe signer activations that lie beyond the
    # checkpoint head it is meant to authenticate. The *selected* key's own
    # activation beyond the head is reported as auth (an unactivated key
    # version, matching the signed-envelope failure category); any other
    # history entry beyond the head makes the document itself inconsistent
    # with the verified checkpoint and is an input error.
    for other_version, entry in signers.items():
        if other_version == first["key_version"]:
            continue
        if entry["activated_event_id"] > checkpoint["event_id"]:
            raise _VerifyError(ERR_INPUT)
    # A signer can only authenticate a checkpoint taken at or after the event
    # that activated its key.
    if checkpoint["event_id"] < signer["activated_event_id"]:
        raise _VerifyError(ERR_AUTH)
    if not verify_checkpoint_auth(
        signer["public_key"],
        genesis_hash,
        checkpoint,
        first["key_version"],
        first["signature"],
    ):
        raise _VerifyError(ERR_AUTH)

